#!/bin/sh
# Agello: turns Bazel's stable-status.txt (agello/workspace_status.sh) into the C++ source that
# litert_lm_get_build_info returns. Usage: make_build_info.sh <stable-status.txt> > out.cc
STATUS="$1"
value() {
  v="$(sed -n "s/^$1 //p" "$STATUS" 2>/dev/null | head -n 1)"
  # JSON string content: escape backslashes and quotes.
  printf '%s' "${v:-$2}" | sed -e 's/\\/\\\\/g' -e 's/"/\\"/g'
}
cat <<EOF
// Generated by agello/make_build_info.sh from Bazel's stable-status.txt. Do not edit.
extern const char kAgelloBuildInfoJson[];
const char kAgelloBuildInfoJson[] = R"json({"build_id":"$(value STABLE_AGELLO_BUILD_ID dev)","litert_lm":"$(value STABLE_AGELLO_LITERT_LM unknown)","litert":"$(value STABLE_AGELLO_LITERT unknown)","ml_drift":"$(value STABLE_AGELLO_ML_DRIFT unknown)","flags":"$(value STABLE_AGELLO_FLAGS unknown)"})json";
EOF
